#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import importlib.util
import os
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION = "0.13.1"

MODIFIED_B64 = {'backend/app/api/v1/endpoints/vision_app_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/automation_manager.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/automation_models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/automation_runtime.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/camera_resource_runtime.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/endpoint_registry.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/repository.py': {'old': '', 'new': ''}, 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/AutomationCodeEditor.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/CameraDeclarationWorkspace.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/EndpointObjectTree.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/IotDeclarationWorkspace.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/WorkspaceTabs.tsx': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64 = {'backend/tests/vision_app/test_vision_app_v1310.py': '', 'frontend/docs/llm_context/updates/v1310_workspace_camera_keyboard_cleanup.md': ''}

MODIFIED = {
    path: {
        "old": base64.b64decode(payload["old"]).decode("utf-8"),
        "new": base64.b64decode(payload["new"]).decode("utf-8"),
    }
    for path, payload in MODIFIED_B64.items()
}
CREATED = {
    path: base64.b64decode(payload).decode("utf-8")
    for path, payload in CREATED_B64.items()
}


def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()
    fe_candidates = []
    be_candidates = []

    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates += [cwd, cwd / "LambdaVisionSuper", cwd.parent / "LambdaVisionSuper"]
    be_candidates += [cwd, cwd / "LambdaVisionSuperBackEnd", cwd.parent / "LambdaVisionSuperBackEnd"]

    frontend = next(
        (
            p for p in fe_candidates
            if (p / "src/Pages/ComputerVisionPage.tsx").exists()
            and (p / "src/components/ComputerVision/WorkspaceTabs.tsx").exists()
        ),
        None,
    )
    backend = next(
        (
            p for p in be_candidates
            if (p / "app/services/vision_app/models.py").exists()
            and (p / "app/services/vision_app/automation_manager.py").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuper frontend. Use --frontend /path/to/LambdaVisionSuper")
    if backend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuperBackEnd. Use --backend /path/to/LambdaVisionSuperBackEnd")

    return frontend, backend


def real_path(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/"):]
    if virtual.startswith("backend/"):
        return backend / virtual[len("backend/"):]
    raise ValueError(virtual)


def modified_state(path: Path, old: str, new: str) -> str:
    if not path.exists():
        return "MISSING"
    current = path.read_text(encoding="utf-8")
    if current == new:
        return "OK"
    if current == old:
        return "UPDATE"
    return "CONFLICT"


def created_state(path: Path, desired: str) -> str:
    if not path.exists():
        return "CREATE"
    return "OK" if path.read_text(encoding="utf-8") == desired else "CONFLICT"


def scan(frontend: Path, backend: Path):
    print("=" * 112)
    print("COMPUTER VISION V0.13.1 — WORKSPACE / CAMERA / KEYBOARD CLEANUP")
    print("=" * 112)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    conflicts = 0

    for virtual, payload in MODIFIED.items():
        state = modified_state(
            real_path(frontend, backend, virtual),
            payload["old"],
            payload["new"],
        )
        print(f"  [{state:12}] {virtual}")
        if state in {"CONFLICT", "MISSING"}:
            conflicts += 1

    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        print(f"  [{state:12}] {virtual}")
        if state == "CONFLICT":
            conflicts += 1

    print()
    print("v0.13.1 contract:")
    print("  Fix + Workspace stale React state bug")
    print("  One Workspace -> one declared Camera via workspace.camera_id")
    print("  Camera resources remain program-wide; Workspace binds exactly one")
    print("  Developer Simulator removed from active UI; simulated drivers hidden as legacy")
    print("  HTTP custom API: {placeholder} params + named IDE arguments")
    print("  Example: camera.pi.focus(x=0.5, y=0.5, w=1.0, h=1.0)")
    print("  keyboard.space / enter / escape / arrows / F1-F12 become live typed endpoints")
    print("  Keyboard signals ignore text/input editing and release cleanly")
    print("  ONLINE = strong green; OFFLINE = strong red")
    print("  Context generator + v0.13.1 handoff note included")

    if conflicts:
        print()
        print(f"[WARN] {conflicts} conflict/base issue(s); apply will stop safely.")

    return 0


def preflight(frontend: Path, backend: Path):
    errors = []

    for virtual, payload in MODIFIED.items():
        state = modified_state(real_path(frontend, backend, virtual), payload["old"], payload["new"])
        if state not in {"UPDATE", "OK"}:
            errors.append(f"{virtual}: {state}")

    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        if state not in {"CREATE", "OK"}:
            errors.append(f"{virtual}: {state}")

    if errors:
        raise RuntimeError("Safe update stopped:\n  - " + "\n  - ".join(errors))


def backup(frontend: Path, backend: Path, paths: list[Path]) -> Path:
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = frontend / ".lambda_updater_backups" / f"computer_vision_v1310_{stamp}"
    root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue
        try:
            rel = path.relative_to(frontend)
            destination = root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(backend)
            destination = root / "backend" / rel
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

    return root


def regenerate_context(frontend: Path, backend: Path):
    generator = frontend / "tools/generate_llm_context_map.py"
    if not generator.exists():
        print("[SKIP] Context generator not found")
        return

    cmd = [
        sys.executable,
        str(generator),
        "--frontend",
        str(frontend),
        "--backend",
        str(backend),
    ]
    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd.extend(["--output-dir", str(frontend / "docs/llm_context")])

    proc = subprocess.run(cmd, cwd=str(frontend), text=True, capture_output=True)
    if proc.returncode != 0:
        raise RuntimeError(
            "Context generator failed:\n"
            + (proc.stdout + "\n" + proc.stderr).strip()
        )
    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(frontend: Path, backend: Path):
    preflight(frontend, backend)

    targets = [
        real_path(frontend, backend, key)
        for key in list(MODIFIED) + list(CREATED)
    ]
    backup_root = backup(frontend, backend, targets)

    for virtual, payload in MODIFIED.items():
        path = real_path(frontend, backend, virtual)
        if path.read_text(encoding="utf-8") != payload["new"]:
            path.write_text(payload["new"], encoding="utf-8")
            print(f"[WRITE] {virtual}")

    for virtual, desired in CREATED.items():
        path = real_path(frontend, backend, virtual)
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print(f"[WRITE] {virtual}")

    print("[INFO] Regenerating LLM context docs...")
    regenerate_context(frontend, backend)

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def python_syntax(backend: Path):
    failures = []
    files = []

    for virtual in list(MODIFIED) + list(CREATED):
        if virtual.startswith("backend/") and virtual.endswith(".py"):
            path = real_path(Path("/unused"), backend, virtual)
            files.append(path)
            try:
                py_compile.compile(str(path), doraise=True)
            except Exception as exc:
                failures.append(f"{path.relative_to(backend)}: {exc}")

    return len(files), failures


def typescript_transpile(frontend: Path):
    files = [
        real_path(frontend, Path("/unused"), virtual)
        for virtual in list(MODIFIED) + list(CREATED)
        if virtual.startswith("frontend/") and virtual.endswith((".ts", ".tsx"))
    ]

    code = r"""
const fs = require("fs");
const ts = require("typescript");
let failed = false;
for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, "utf8");
  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });
  const errors = (result.diagnostics || []).filter(
    (d) => d.category === ts.DiagnosticCategory.Error,
  );
  if (errors.length) {
    failed = true;
    console.error("TS_ERROR", file);
    for (const d of errors) {
      console.error(ts.flattenDiagnosticMessageText(d.messageText, "\n"));
    }
  }
}
process.exit(failed ? 1 : 0);
"""

    env = dict(os.environ)
    npm_root = subprocess.run(["npm", "root", "-g"], text=True, capture_output=True)
    if npm_root.returncode == 0 and npm_root.stdout.strip():
        env["NODE_PATH"] = npm_root.stdout.strip() + (
            os.pathsep + env["NODE_PATH"] if env.get("NODE_PATH") else ""
        )

    return subprocess.run(
        ["node", "-e", code, *map(str, files)],
        cwd=str(frontend),
        env=env,
        text=True,
        capture_output=True,
    )


def backend_smoke(backend: Path):
    code = r"""
from app.services.vision_app.automation_models import (
    AutomationServiceDefinition,
    AutomationSystemState,
)
from app.services.vision_app.automation_runtime import (
    AutomationExecutionContext,
    SafeAutomationInterpreter,
    validate_script,
)
from app.services.vision_app.endpoint_registry import EndpointRegistry
from app.services.vision_app.models import (
    CameraApiParameter,
    CameraCustomApi,
    CameraDeclaration,
    CameraDeclarationConfig,
    VisionProgramDefinition,
    WorkspaceDefinition,
)

camera = CameraDeclaration(
    declaration_id="pi",
    alias="pi",
    driver="http",
    custom_apis=[
        CameraCustomApi(
            api_id="focus",
            alias="focus",
            path_template="/focus?x={x}&y={y}&w={w}&h={h}",
            parameters=[
                CameraApiParameter(name="x", default=0.5),
                CameraApiParameter(name="y", default=0.5),
                CameraApiParameter(name="w", default=1.0),
                CameraApiParameter(name="h", default=1.0),
            ],
        )
    ],
)
program = VisionProgramDefinition(
    program_id="smoke",
    name="Smoke",
    cameras=CameraDeclarationConfig(devices=[camera]),
    workspaces=[
        WorkspaceDefinition(
            workspace_id="front",
            name="Front",
            alias="front",
            camera_id="pi",
            input_binding="camera.pi.Current_image",
        )
    ],
)
state = AutomationSystemState(
    program_id="smoke",
    keyboard_states={"space": True},
)
eps = {e.path: e for e in EndpointRegistry().build(program, state=state)}

assert eps["keyboard.space"].last_value is True
assert eps["keyboard.space"].allowed_values == ["ON", "OFF"]
assert eps["workspace.front"].path == "workspace.front"
assert eps["camera.pi.focus"].parameters[0]["name"] == "x"

script = (
    "if keyboard.space == ON:\n"
    "    camera.pi.focus(x=0.5, y=0.5, w=1.0, h=1.0)\n"
)
assert validate_script(script) == []
calls = []
service = AutomationServiceDefinition(
    service_id="test",
    name="Test",
    script=script,
)
ctx = AutomationExecutionContext(
    program=program,
    snapshot=None,
    event={},
    read_endpoint=lambda path: True if path == "keyboard.space" else None,
    write_endpoint=lambda path, value, dry: None,
    call_action=lambda path, args, kwargs, dry: calls.append((path, args, kwargs)),
    trace=lambda entry: None,
    dry_run=True,
)
result = SafeAutomationInterpreter(ctx, service).execute(script)
assert result.ok
assert calls == [
    (
        "camera.pi.focus",
        [],
        {"x": 0.5, "y": 0.5, "w": 1.0, "h": 1.0},
    )
]
print("VISION_V1310_SMOKE_OK", len(eps), calls[0][2])
"""

    return subprocess.run(
        [sys.executable, "-c", code],
        cwd=str(backend),
        text=True,
        capture_output=True,
    )


def verify(frontend: Path, backend: Path, *, skip_build: bool = False):
    print("=" * 112)
    print("VERIFY COMPUTER VISION V0.13.1")
    print("=" * 112)

    failures = 0

    models = (backend / "app/services/vision_app/models.py").read_text(encoding="utf-8")
    runtime = (backend / "app/services/vision_app/automation_runtime.py").read_text(encoding="utf-8")
    manager = (backend / "app/services/vision_app/automation_manager.py").read_text(encoding="utf-8")
    registry = (backend / "app/services/vision_app/endpoint_registry.py").read_text(encoding="utf-8")
    page = (frontend / "src/Pages/ComputerVisionPage.tsx").read_text(encoding="utf-8")
    camera_ui = (frontend / "src/components/ComputerVision/CameraDeclarationWorkspace.tsx").read_text(encoding="utf-8")
    iot_ui = (frontend / "src/components/ComputerVision/IotDeclarationWorkspace.tsx").read_text(encoding="utf-8")
    tabs = (frontend / "src/components/ComputerVision/WorkspaceTabs.tsx").read_text(encoding="utf-8")
    editor = (frontend / "src/components/ComputerVision/AutomationCodeEditor.tsx").read_text(encoding="utf-8")

    checks = [
        (
            "+ Workspace stale-state fix",
            "setProgram(prev=>" in page
            and "onChange={workspaces=>" in page
            and "camera_id:''" in tabs,
        ),
        (
            "One camera per Workspace contract",
            'camera_id: str = "camera_main"' in models
            and "assigned camera" in page
            and "activeWorkspace.camera_id" in page,
        ),
        (
            "Simulator removed from active UI",
            "DeveloperSimulatorWorkspace" not in page
            and "key:'simulator'" not in page
            and ">Simulated</option>" not in iot_ui
            and ">Simulated</option>" not in camera_ui,
        ),
        (
            "HTTP URL placeholder guide",
            "URL parameter binding" in camera_ui
            and "Sync from {'{...}'}" in camera_ui
            and "Resolved with defaults" in camera_ui,
        ),
        (
            "Safe DSL named arguments",
            "ast.keyword" in runtime
            and "kwargs =" in runtime
            and "call_action(path, args, kwargs" in runtime,
        ),
        (
            "Camera custom endpoints expose parameter metadata",
            "parameters=params" in registry
            and "Params:" in editor,
        ),
        (
            "Keyboard typed object",
            'path="keyboard"' in registry
            and 'f"keyboard.{key}"' in registry
            and "keyboard.space" in (
                frontend
                / "docs/llm_context/updates/v1310_workspace_camera_keyboard_cleanup.md"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Keyboard frontend bridge",
            "automationKeyboard(program.program_id" in page
            and "/automation/keyboard" in (
                backend / "app/api/v1/endpoints/vision_app_api.py"
            ).read_text(encoding="utf-8"),
        ),
        (
            "ONLINE/OFFLINE high contrast colors",
            "bg-[#1f6b38]" in page
            and "bg-[#5f2120]" in page,
        ),
        (
            "Program v6 migration",
            "version: int = 6" in models
            and 'data["version"] = max(6' in (
                backend / "app/services/vision_app/repository.py"
            ).read_text(encoding="utf-8"),
        ),
        (
            "v0.13.1 regression test",
            (backend / "tests/vision_app/test_vision_app_v1310.py").exists(),
        ),
        (
            "v0.13.1 handoff MD",
            (
                frontend
                / "docs/llm_context/updates/v1310_workspace_camera_keyboard_cleanup.md"
            ).exists(),
        ),
        (
            "Context generator v0.13.1",
            "v0.13.1 Computer Vision" in (
                frontend / "tools/generate_llm_context_map.py"
            ).read_text(encoding="utf-8"),
        ),
    ]

    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    count, syntax_failures = python_syntax(backend)
    if syntax_failures:
        print("[FAIL] Python syntax")
        for issue in syntax_failures:
            print("  -", issue)
        failures += len(syntax_failures)
    else:
        print(f"[OK] Python syntax ({count} changed/new backend files)")

    smoke = backend_smoke(backend)
    if smoke.returncode == 0:
        print("[OK] Workspace/Camera/Keyboard backend smoke")
        if smoke.stdout.strip():
            print(smoke.stdout.strip())
    else:
        print("[FAIL] Workspace/Camera/Keyboard backend smoke")
        print((smoke.stdout + "\n" + smoke.stderr).strip())
        failures += 1

    if importlib.util.find_spec("pytest") is not None:
        full_ready = (
            (backend / "app/core").exists()
            and (backend / "app/services/vision_labs").exists()
            and (backend / "tests/vision_app").exists()
        )
        targets = (
            ["tests/vision_app"]
            if full_ready
            else ["tests/vision_app/test_vision_app_v1310.py"]
        )
        proc = subprocess.run(
            [sys.executable, "-m", "pytest", "-q", *targets],
            cwd=str(backend),
            text=True,
            capture_output=True,
        )
        if proc.returncode == 0:
            print("[OK] Vision App regression tests")
            if proc.stdout.strip():
                print(proc.stdout.strip())
        else:
            print("[FAIL] Vision App regression tests")
            print((proc.stdout + "\n" + proc.stderr).strip())
            failures += 1
    else:
        print("[SKIP] pytest unavailable")

    ts = typescript_transpile(frontend)
    ts_text = (ts.stdout + "\n" + ts.stderr).strip()
    if ts.returncode == 0:
        print("[OK] TypeScript syntax/transpile")
    elif "Cannot find module 'typescript'" in ts_text or "MODULE_NOT_FOUND" in ts_text:
        print("[SKIP] TypeScript module unavailable to Node")
    else:
        print("[FAIL] TypeScript syntax/transpile")
        print(ts_text)
        failures += 1

    if not skip_build and (frontend / "package.json").exists() and (frontend / "node_modules").exists():
        proc = subprocess.run(["npm", "run", "build"], cwd=str(frontend))
        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    try:
        regenerate_context(frontend, backend)
        arch = frontend / "docs/llm_context/SYSTEM_ARCHITECTURE.md"
        ok = arch.exists()
        print(f"[{'OK' if ok else 'FAIL'}] Regenerated LLM context docs")
        failures += 0 if ok else 1
    except Exception as exc:
        print(f"[FAIL] Context regeneration: {exc}")
        failures += 1

    if failures:
        print(f"[FAIL] v0.13.1 verification finished with {failures} issue(s).")
        return 1

    print("[OK] Computer Vision v0.13.1 workspace/camera/keyboard cleanup verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify"])
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument("--skip-build", action="store_true")
    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(args.frontend, args.backend)

        if args.command == "scan":
            return scan(frontend, backend)
        if args.command == "apply":
            return apply(frontend, backend)
        return verify(frontend, backend, skip_build=args.skip_build)

    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
